def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            objs.append((color, cells))
    # Slide each rigid object right until it reaches the boundary or another object.
    positions = [list(cells) for color, cells in objs]
    while True:
        occupied = set(p for cells in positions for p in cells)
        movable = []
        for i, cells in enumerate(positions):
            if all(c+1 < w and (r, c+1) not in occupied for r, c in cells):
                movable.append(i)
        if not movable:
            break
        for i in movable:
            positions[i] = [(r, c+1) for r, c in positions[i]]
    out = [[0]*w for _ in range(h)]
    for (color, _), cells in zip(objs, positions):
        for r, c in cells:
            out[r][c] = color
    return out

