def transform(grid):
    h, w = len(grid), len(grid[0])
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = y+dy, x+dx
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); stack.append(p)
            objects.append((color, cells))
    # Let objects furthest right settle first, then pack the rest against them.
    objects.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
    settled = []
    for color, cells in objects:
        own = set(cells)
        while True:
            nxt = {(r, c+1) for r, c in cells}
            if any(c >= w for r, c in nxt):
                break
            if any(any((r, c) in other for r, c in nxt) for _, other in settled):
                break
            cells = sorted(nxt)
        settled.append((color, cells))
    out = [[0]*w for _ in range(h)]
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
